/**
 * Seed helpers — shared by the demo-mode data layer (SvelteKit) and the
 * Studio seed builder (`studio/seed/build-seed.ts`, run with Node's native
 * TypeScript support). Keep this file free of non-erasable TS syntax.
 */

export type SeedDoc = { _id: string; _type: string; [key: string]: unknown };

