export type DemoImageName = keyof typeof DEMO_IMAGES;

let keyCounter = 0;
/** Deterministic `_key` generator (stable across runs because module order is stable). */
export function k(): string {
	keyCounter += 1;
	return `k${keyCounter.toString(36).padStart(5, '0')}`;
}

/** Demo image field. Asset refs follow Sanity's `image-<id>-<w>x<h>-<ext>` convention
 *  so width/height can be derived without a network round-trip. */
export function img(name: DemoImageName, alt: string, caption?: string) {
	const d = DEMO_IMAGES[name];
	return {
		_type: 'imageWithAlt',
		alt,
		...(caption ? { caption } : {}),
		asset: { _type: 'reference', _ref: `image-demo${name}-${d.w}x${d.h}-jpg` }
	};
}

/** Demo file field (e.g. a brochure PDF). */
export function file(name: string, title: string) {
	return {
		_type: 'file',
		title,
		asset: { _type: 'reference', _ref: `file-demo${name}-pdf` }
	};
}

export function ref(id: string, withKey = false) {
	return withKey ? { _type: 'reference', _ref: id, _key: k() } : { _type: 'reference', _ref: id };
}

export const refs = (ids: string[]) => ids.map((id) => ref(id, true));

export function slug(current: string) {
	return { _type: 'slug', current };
}

/* ── Portable Text ─────────────────────────────────────────────────────────── */
type Span = { _type: 'span'; _key: string; text: string; marks: string[] };

function spans(text: string): { children: Span[]; markDefs: unknown[] } {
	// Supports **bold** and *italic* inline markers for convenience.
	const children: Span[] = [];
	const re = /(\*\*[^*]+\*\*|\*[^*]+\*)/g;
	let last = 0;
	for (const m of text.matchAll(re)) {
		const idx = m.index ?? 0;
		if (idx > last)
			children.push({ _type: 'span', _key: k(), text: text.slice(last, idx), marks: [] });
		const raw = m[0];
		const bold = raw.startsWith('**');
		children.push({
			_type: 'span',
			_key: k(),
			text: raw.slice(bold ? 2 : 1, bold ? -2 : -1),
			marks: [bold ? 'strong' : 'em']
		});
		last = idx + raw.length;
	}
	if (last < text.length)
		children.push({ _type: 'span', _key: k(), text: text.slice(last), marks: [] });
	return { children, markDefs: [] };
}

export function p(text: string) {
	return { _type: 'block', _key: k(), style: 'normal', ...spans(text) };
}
export function h2(text: string) {
	return { _type: 'block', _key: k(), style: 'h2', ...spans(text) };
}
export function h3(text: string) {
	return { _type: 'block', _key: k(), style: 'h3', ...spans(text) };
}
export function quote(text: string) {
	return { _type: 'block', _key: k(), style: 'blockquote', ...spans(text) };
}
export function ul(items: string[]) {
	return items.map((t) => ({
		_type: 'block',
		_key: k(),
		style: 'normal',
		listItem: 'bullet',
		level: 1,
		...spans(t)
	}));
}
export function ol(items: string[]) {
	return items.map((t) => ({
		_type: 'block',
		_key: k(),
		style: 'normal',
		listItem: 'number',
		level: 1,
		...spans(t)
	}));
}
export function callout(tone: 'note' | 'tip' | 'warning', text: string) {
	return { _type: 'callout', _key: k(), tone, text };
}
export function inlineImage(name: DemoImageName, alt: string, caption?: string) {
	return { ...img(name, alt, caption), _key: k() };
}

/** Flatten helper so lists (arrays of blocks) can sit inline in body arrays. */
export function body(...parts: unknown[]) {
	return parts.flat();
}

/* ── Reusable objects ─────────────────────────────────────────────────────── */
export function cta(
	label: string,
	href: string,
	variant: 'primary' | 'secondary' | 'ghost' = 'primary',
	action: 'link' | 'consultation' | 'whatsapp' = 'link'
) {
	return { _type: 'cta', label, href, variant, action };
}

export function stat(value: number, label: string, suffix = '', prefix = '', decimals = 0) {
	return { _type: 'stat', _key: k(), value, label, suffix, prefix, decimals };
}

export function feature(icon: string, title: string, description: string) {
	return { _type: 'feature', _key: k(), icon, title, description };
}

export function seo(title: string, description: string) {
	return { _type: 'seo', title, description };
}
